import type { ExpoConfig } from 'expo/config'

/**
 * The single source of truth for native configuration.
 *
 * `ios/` and `android/` are gitignored and regenerated by `expo prebuild`, so
 * anything that would normally be edited in Xcode or Android Studio has to be
 * expressed here or in a config plugin. See docs/adr/0001.
 */

// Fonts are embedded at BUILD time via the config plugin rather than loaded at
// runtime with useFonts. Every title in this design is serif, so a runtime font
// gate means a visible flash or a blocked splash on every cold start.
const FONTS = [
  'EBGaramond-Regular',
  'EBGaramond-Medium',
  'EBGaramond-Italic',
  'EBGaramond-MediumItalic',
  'InterTight-Regular',
  'InterTight-Medium',
  'InterTight-SemiBold',
  'InterTight-Bold',
  'JetBrainsMono-Regular',
  'JetBrainsMono-Medium',
].map(name => `./assets/fonts/${name}.ttf`)

const config: ExpoConfig = {
  name: 'photu',
  slug: 'photu',
  scheme: 'photu',
  version: '0.1.0',
  orientation: 'portrait',
  // 'light' because the shipping palette (`quiet`) is light and the app does not
  // follow the OS theme: palette is a product choice here, not a system one.
  userInterfaceStyle: 'light',
  // No newArchEnabled flag — the New Architecture is unconditional from SDK 54
  // onward, and the key was removed from the config type.

  // The shipping palette's background (`quiet`). Set natively so the very first
  // frame — before React mounts — is already the app's colour rather than white.
  backgroundColor: '#F7F6F3',

  icon: './assets/icon.png',
  // Splash is configured through the expo-splash-screen plugin below; the
  // top-level `splash` key was removed from ExpoConfig.

  ios: {
    bundleIdentifier: 'app.photu.mobile',
    supportsTablet: false,
    infoPlist: {
      // Local-network access for DEBUG builds only. Presigned upload URLs point at
      // the developer's LAN address over plain http, which iOS App Transport
      // Security blocks by default — and the failure surfaces as an opaque
      // URLSession error rather than anything mentioning ATS.
      NSAllowsLocalNetworking: true,
      NSLocalNetworkUsageDescription: 'photu connects to your development server on this network.',
    },
    associatedDomains: ['applinks:photu.app'],
  },

  android: {
    package: 'app.photu.mobile',
    adaptiveIcon: {
      foregroundImage: './assets/adaptive-icon.png',
      backgroundColor: '#15171A',
    },
    // No edgeToEdgeEnabled flag: edge-to-edge is the default on Android from
    // SDK 54 onward, which is why every screen goes through <Screen> and its
    // safe-area insets rather than assuming an opaque system bar.
    intentFilters: [
      {
        action: 'VIEW',
        autoVerify: true,
        data: [{ scheme: 'https', host: 'photu.app', pathPrefix: '/a' }],
        category: ['BROWSABLE', 'DEFAULT'],
      },
    ],
  },

  plugins: [
    'expo-router',
    [
      'expo-splash-screen',
      {
        image: './assets/splash-icon.png',
        // The palette background, so the launch image and the first React frame
        // are the same colour — no white flash between them.
        backgroundColor: '#F7F6F3',
        imageWidth: 160,
      },
    ],
    ['expo-font', { fonts: FONTS }],
    // NOTE: react-native-worklets/plugin does NOT belong here. It is a BABEL
    // plugin (see babel.config.js) — listing it as an Expo config plugin makes
    // prebuild fail while evaluating this file, with an error about
    // 'workletNumber' that says nothing about the real cause.
  ],

  experiments: {
    // router.push('/album/…') becomes type-checked against the actual route tree.
    typedRoutes: true,
  },

  extra: {
    // Read via expo-constants. The API base URL must be the LAN address on a real
    // device: localhost resolves to the device itself.
    apiBaseUrl: process.env.EXPO_PUBLIC_API_BASE_URL ?? 'http://10.0.2.2:8080',
  },
}

export default config
